package main

// Deterministic fixture generation.
//
// The large performance fixture is not stored in the repository: it is
// regenerated byte for byte from a fixed seed. The generator uses its own
// xorshift64* so the bytes do not depend on the Go version's math/rand.

import (
	"bufio"
	"fmt"
	"io"
	"strings"
)

// LargeFixtureSeed is frozen. Changing it changes the fixture.
const LargeFixtureSeed uint64 = 0x5354524541_4d3031

type rng struct{ state uint64 }

func newRNG(seed uint64) *rng {
	if seed == 0 {
		seed = 1
	}
	return &rng{state: seed}
}

func (r *rng) next() uint64 {
	x := r.state
	x ^= x >> 12
	x ^= x << 25
	x ^= x >> 27
	r.state = x
	return x * 2685821657736338717
}

func (r *rng) intn(n int) int {
	return int(r.next() % uint64(n))
}

var genCategories = []string{"purchase", "refund", "subscription", "adjustment"}
var genStatuses = []string{"settled", "pending", "failed"}

// generateTo writes a JSONL fixture of n lines straight to w and returns the
// number of bytes written.
//
// The validator uses this instead of generate for the large fixture: measuring
// a child process's peak memory is only meaningful while the measuring process
// is itself small, and holding a 60 MiB fixture in the parent would both
// inflate the parent and follow the child across fork.
func generateTo(w io.Writer, n int, seed uint64) (int64, error) {
	writer := bufio.NewWriterSize(w, 1<<20)
	var written int64
	for _, line := range lines(n, seed) {
		count, err := writer.WriteString(line)
		if err != nil {
			return written, err
		}
		written += int64(count)
	}
	if err := writer.Flush(); err != nil {
		return written, err
	}
	return written, nil
}

// generate builds a JSONL fixture of n lines.
//
// Roughly one line in 613 is invalid, cycling through every rejection reason,
// and roughly one in 997 repeats an earlier event id. Everything else is a
// valid event.
func generate(n int, seed uint64) []byte {
	var builder strings.Builder
	builder.Grow(n * 150)
	for _, line := range lines(n, seed) {
		builder.WriteString(line)
	}
	return []byte(builder.String())
}

// lines yields the fixture one newline-terminated line at a time.
func lines(n int, seed uint64) func(func(int, string) bool) {
	return func(yield func(int, string) bool) {
		random := newRNG(seed)
		baseEpoch := int64(1_767_225_600) // 2026-01-01T00:00:00Z

		for i := 0; i < n; i++ {
			customer := fmt.Sprintf("cust-%05d", random.intn(5000))
			offset := random.intn(30 * 24 * 3600)
			stamp := formatEpoch(baseEpoch + int64(offset))
			category := genCategories[random.intn(len(genCategories))]
			status := genStatuses[random.intn(len(genStatuses))]
			amount := int64(random.intn(500_000) + 1)
			if category == "refund" {
				amount = -amount
			}

			var line string
			switch {
			case i > 0 && i%997 == 0:
				// A repeat of an earlier event id; everything else is valid.
				line = fmt.Sprintf(
					`{"event_id":"evt-%09d","customer_id":%q,"timestamp":%q,"category":%q,"amount":%d,"status":%q}`,
					i-500, customer, stamp, category, amount, status)
			case i%613 == 0:
				line = invalidLine(i/613, i, customer, stamp, category, amount, status)
			default:
				line = fmt.Sprintf(
					`{"event_id":"evt-%09d","customer_id":%q,"timestamp":%q,"category":%q,"amount":%d,"status":%q}`,
					i, customer, stamp, category, amount, status)
			}

			if !yield(i, line+"\n") {
				return
			}
		}
	}
}

func invalidLine(variant, i int, customer, stamp, category string, amount int64, status string) string {
	switch variant % 6 {
	case 0:
		return `{"event_id":"evt-` + fmt.Sprintf("%09d", i) + `","customer_id":` // truncated JSON
	case 1:
		return fmt.Sprintf(
			`{"event_id":"evt-%09d","customer_id":%q,"category":%q,"amount":%d,"status":%q}`,
			i, customer, category, amount, status)
	case 2:
		return fmt.Sprintf(
			`{"event_id":"evt-%09d","customer_id":%q,"timestamp":%q,"category":"barter","amount":%d,"status":%q}`,
			i, customer, stamp, amount, status)
	case 3:
		return fmt.Sprintf(
			`{"event_id":"evt-%09d","customer_id":%q,"timestamp":%q,"category":%q,"amount":12.5,"status":%q}`,
			i, customer, stamp, category, status)
	case 4:
		return fmt.Sprintf(
			`{"event_id":"evt-%09d","customer_id":%q,"timestamp":%q,"category":%q,"amount":%d,"status":"queued"}`,
			i, customer, stamp, category, amount)
	default:
		return fmt.Sprintf(
			`{"event_id":"evt-%09d","customer_id":"","timestamp":%q,"category":%q,"amount":%d,"status":%q}`,
			i, stamp, category, amount, status)
	}
}

func formatEpoch(epoch int64) string {
	days := epoch / 86400
	secondsOfDay := epoch % 86400
	year, month, day := civilFromDays(days)
	return fmt.Sprintf("%04d-%02d-%02dT%02d:%02d:%02dZ",
		year, month, day, secondsOfDay/3600, (secondsOfDay%3600)/60, secondsOfDay%60)
}

// civilFromDays converts days since the Unix epoch to a civil date without
// touching the time package, so the fixture bytes cannot drift with tzdata.
func civilFromDays(z int64) (int64, int64, int64) {
	z += 719468
	era := z / 146097
	if z < 0 {
		era = (z - 146096) / 146097
	}
	doe := z - era*146097
	yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
	y := yoe + era*400
	doy := doe - (365*yoe + yoe/4 - yoe/100)
	mp := (5*doy + 2) / 153
	d := doy - (153*mp+2)/5 + 1
	m := mp + 3
	if mp >= 10 {
		m = mp - 9
	}
	if m <= 2 {
		y++
	}
	return y, m, d
}
